sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  c.searchText = "";
  c.activeFilter = "all";
  c.currentPage = 1;
  c.pageSize = 4;
  c.submittingId = "";
  c.notice = "";
  c.noticeType = "success";

  c.filters = [
    { label: "All rentals", value: "all" },
    { label: "Due soon", value: "soon" },
    { label: "Overdue", value: "overdue" },
    { label: "Requested", value: "requested" }
  ];

  c.data.rentals = c.data.rentals || [];

  c.filteredRentals = function() {
    var search = (c.searchText || "").toLowerCase().trim();

    return c.data.rentals.filter(function(rental) {
      var matchesSearch = !search ||
        (rental.assetName || "").toLowerCase().indexOf(search) > -1 ||
        (rental.number || "").toLowerCase().indexOf(search) > -1 ||
        (rental.type || "").toLowerCase().indexOf(search) > -1;

      var matchesFilter = c.activeFilter === "all" ||
        (c.activeFilter === "soon" &&
          rental.isDueSoon && !rental.isOverdue) ||
        (c.activeFilter === "overdue" && rental.isOverdue) ||
        (c.activeFilter === "requested" && rental.requested);

      return matchesSearch && matchesFilter;
    });
  };

  c.filterCount = function(filter) {
    if (filter === "all") return c.data.rentals.length;

    return c.data.rentals.filter(function(rental) {
      if (filter === "soon") {
        return rental.isDueSoon && !rental.isOverdue;
      }
      if (filter === "overdue") return rental.isOverdue;
      if (filter === "requested") return rental.requested;
      return false;
    }).length;
  };

  c.dueSoonCount = function() {
    return c.filterCount("soon");
  };

  c.requestedCount = function() {
    return c.filterCount("requested");
  };

  c.totalPages = function() {
    return Math.max(
      1,
      Math.ceil(c.filteredRentals().length / c.pageSize)
    );
  };

  c.pageRentals = function() {
    var start = (c.currentPage - 1) * c.pageSize;
    return c.filteredRentals().slice(start, start + c.pageSize);
  };

  c.startItem = function() {
    return c.filteredRentals().length
      ? (c.currentPage - 1) * c.pageSize + 1
      : 0;
  };

  c.endItem = function() {
    return Math.min(
      c.currentPage * c.pageSize,
      c.filteredRentals().length
    );
  };

  c.pageNumbers = function() {
    var pages = [];
    for (var i = 1; i <= c.totalPages(); i++) {
      pages.push(i);
    }
    return pages;
  };

  c.changePage = function(page) {
    if (page >= 1 && page <= c.totalPages()) {
      c.currentPage = page;
    }
  };

  c.setFilter = function(filter) {
    c.activeFilter = filter;
    c.currentPage = 1;
  };

  c.resetFilters = function() {
    c.searchText = "";
    c.activeFilter = "all";
    c.currentPage = 1;
  };

  $scope.$watchGroup([
    function() { return c.searchText; },
    function() { return c.activeFilter; }
  ], function() {
    c.currentPage = 1;
  });

  c.requestRenewal = function(rental) {
    if (!rental || !rental.id || rental.requested ||
        c.submittingId) {
      return;
    }

    if (rental.isOverdue) {
      c.notice = "Overdue items need assistance from the campus desk.";
      c.noticeType = "error";
      return;
    }

    c.notice = "";
    c.submittingId = rental.id;

    c.server.get({
      action: "requestRenewal",
      rentalId: rental.id
    }).then(function(response) {
      var result = response.data || {};

      if (result.success) {
        rental.requested = true;
        rental.renewalRequested = true;

        c.notice = result.message ||
          "Your renewal request has been submitted.";
        c.noticeType = "success";
      } else {
        c.notice = result.message ||
          "We couldn't submit your request. Please try again.";
        c.noticeType = "error";
      }
    }, function() {
      c.notice = "A server error occurred. Please try again.";
      c.noticeType = "error";
    }).finally(function() {
      c.submittingId = "";
    });
  };
};

sp_widget.css:
.co-renew-page {
  --renew-purple: #8062c7;
  --renew-purple-dark: #39285f;
  --renew-border: #e6dcf7;
  --renew-muted: #81749b;
  --renew-bg: #f3f8f9;
  font-family: inherit;
  color: var(--renew-purple-dark);
  background: var(--renew-bg);
  min-height: 100vh;
  padding: 10px;
  box-sizing: border-box;
}

.co-renew-page *,
.co-renew-page *::before,
.co-renew-page *::after {
  box-sizing: border-box;
}

.co-renew-layout {
  display: grid;
  grid-template-columns: 182px minmax(0, 1fr);
  gap: 20px;
  max-width: 1180px;
  margin: 0 auto;
  align-items: stretch;
}

/* Sidebar: shared CampusOps proportions */
.co-renew-sidebar {
  background: linear-gradient(180deg, #f8f4ff 0%, #f2edfc 100%);
  border: 1px solid var(--renew-border);
  border-radius: 17px;
  padding: 18px 11px 12px;
  display: flex;
  flex-direction: column;
  min-height: 680px;
}

.co-renew-brand {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 6px 27px;
  color: var(--renew-purple-dark);
  text-decoration: none;
}

.co-renew-brand-mark {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: var(--renew-purple);
  color: white;
  font-size: 16px;
  font-weight: 700;
  flex-shrink: 0;
}

.co-renew-brand strong,
.co-renew-brand small {
  display: block;
}

.co-renew-brand strong {
  font-size: 12px;
  line-height: 1.4;
}

.co-renew-brand small {
  font-size: 9px;
  color: var(--renew-muted);
  margin-top: 2px;
}

.co-renew-nav-label {
  margin: 0 8px 9px;
  color: #9485b2;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 1px;
}

.co-renew-nav {
  min-height: 34px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  margin-bottom: 3px;
  border-radius: 8px;
  color: #5d4a80;
  font-size: 10px;
  text-decoration: none;
  transition: background .16s ease, color .16s ease;
}

.co-renew-nav > span {
  width: 13px;
  text-align: center;
  color: var(--renew-purple);
  font-size: 13px;
}

.co-renew-nav:hover,
.co-renew-nav-active {
  background: #e8defb;
  color: #4c347e;
}

.co-renew-account-label {
  margin-top: 23px;
}

.co-renew-sidebar-bottom {
  margin-top: auto;
  padding: 13px 5px 0;
  border-top: 1px solid #e2d8f2;
  display: flex;
  align-items: center;
  gap: 8px;
}

.co-renew-avatar {
  width: 29px;
  height: 29px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #e7dcfb;
  color: #6547a5;
  font-size: 11px;
  font-weight: 700;
}

.co-renew-sidebar-bottom strong,
.co-renew-sidebar-bottom small {
  display: block;
  overflow-wrap: anywhere;
}

.co-renew-sidebar-bottom strong {
  font-size: 9px;
}

.co-renew-sidebar-bottom small {
  margin-top: 3px;
  font-size: 8px;
  color: var(--renew-muted);
}

/* Main page */
.co-renew-main {
  min-width: 0;
  padding: 5px 0 0;
}

.co-renew-page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 15px;
  margin-bottom: 19px;
}

.co-renew-eyebrow {
  margin-bottom: 7px;
  color: var(--renew-purple);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

.co-renew-page-header h1 {
  margin: 0 0 5px;
  font-size: clamp(22px, 2.2vw, 28px);
  line-height: 1.2;
  letter-spacing: -.5px;
  font-weight: 750;
  color: #30224e;
}

.co-renew-page-header p,
.co-renew-intro p,
.co-renew-section-heading p {
  margin: 0;
  color: var(--renew-muted);
  font-size: 10px;
  line-height: 1.6;
}

.co-renew-outline-link {
  flex-shrink: 0;
  border: 1px solid var(--renew-border);
  background: #fff;
  color: #6547a5;
  padding: 9px 12px;
  border-radius: 9px;
  font-size: 9px;
  font-weight: 600;
  text-decoration: none;
}

.co-renew-outline-link:hover {
  background: #f5f0ff;
  border-color: #cbb8ef;
}

/* Compact intro, no oversized AI-style hero */
.co-renew-intro {
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 16px;
  margin-bottom: 13px;
  background: #fff;
  border: 1px solid var(--renew-border);
  border-radius: 12px;
}

.co-renew-intro-icon {
  width: 39px;
  height: 39px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: #f0e8ff;
  color: var(--renew-purple);
  font-size: 23px;
}

.co-renew-intro h2 {
  margin: 0 0 5px;
  font-size: 14px;
  font-weight: 700;
}

/* Small summary strip */
.co-renew-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  background: #fff;
  border: 1px solid var(--renew-border);
  border-radius: 11px;
  padding: 13px 4px;
  margin-bottom: 24px;
}

.co-renew-stats > div {
  min-width: 0;
  padding: 0 15px;
  border-right: 1px solid #eee6f8;
}

.co-renew-stats > div:last-child {
  border-right: 0;
}

.co-renew-stats span,
.co-renew-stats strong {
  display: block;
}

.co-renew-stats span {
  font-size: 9px;
  color: var(--renew-muted);
  margin-bottom: 5px;
}

.co-renew-stats strong {
  font-size: 19px;
  color: #38245d;
}

/* Rental list and search */
.co-renew-list-section {
  margin-bottom: 20px;
}

.co-renew-section-heading {
  margin-bottom: 11px;
}

.co-renew-section-heading h2 {
  margin: 0 0 4px;
  font-size: 16px;
  font-weight: 750;
}

.co-renew-search {
  display: flex;
  align-items: center;
  gap: 9px;
  height: 39px;
  padding: 0 12px;
  margin-bottom: 10px;
  border: 1px solid var(--renew-border);
  border-radius: 10px;
  background: #fff;
}

.co-renew-search > span {
  color: var(--renew-purple);
  font-size: 16px;
}

.co-renew-search input {
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: #382b54;
  font-family: inherit;
  font-size: 10px;
}

.co-renew-filter-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 12px;
}

.co-renew-filter-row button {
  border: 1px solid var(--renew-border);
  border-radius: 8px;
  background: #fff;
  color: #6b598b;
  padding: 7px 10px;
  font-family: inherit;
  font-size: 9px;
  cursor: pointer;
}

.co-renew-filter-row button:hover {
  border-color: #b9a3e6;
}

.co-renew-filter-row button.selected {
  border-color: var(--renew-purple);
  background: var(--renew-purple);
  color: #fff;
}

/* Two-column cards, compact like Browse Assets */
.co-renew-card-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.co-renew-card {
  min-width: 0;
  padding: 14px;
  background: #fff;
  border: 1px solid var(--renew-border);
  border-radius: 13px;
  transition: border-color .15s ease, box-shadow .15s ease;
}

.co-renew-card:hover {
  border-color: #cbb8ef;
  box-shadow: 0 4px 13px rgba(70, 48, 105, .05);
}

.co-renew-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 12px;
}

.co-renew-resource-icon {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: #f0e8ff;
  color: var(--renew-purple);
  font-size: 16px;
}

.co-renew-status {
  padding: 5px 8px;
  border-radius: 20px;
  font-size: 8px;
  font-weight: 700;
  white-space: nowrap;
}

.co-renew-status::before {
  content: "• ";
}

.co-renew-status.status-active {
  background: #e9f7ef;
  color: #26784e;
}

.co-renew-status.status-due {
  background: #fff3df;
  color: #a76513;
}

.co-renew-status.status-overdue {
  background: #fdebef;
  color: #b23a53;
}

.co-renew-status.status-requested {
  background: #f0e8ff;
  color: #6947a7;
}

.co-renew-resource-type {
  margin-bottom: 4px;
  color: #8b7ba7;
  font-size: 8px;
  letter-spacing: .5px;
}

.co-renew-card h3 {
  margin: 0 0 4px;
  color: #35234f;
  font-size: 13px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.co-renew-number {
  margin: 0 0 12px;
  color: var(--renew-muted);
  font-size: 9px;
}

.co-renew-details {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  padding: 11px 0;
  border-top: 1px solid #eee7f8;
  border-bottom: 1px solid #eee7f8;
}

.co-renew-details span,
.co-renew-details strong {
  display: block;
  overflow-wrap: anywhere;
}

.co-renew-details span {
  margin-bottom: 5px;
  color: var(--renew-muted);
  font-size: 8px;
}

.co-renew-details strong {
  color: #44315f;
  font-size: 9px;
}

.co-renew-note {
  margin: 10px 0;
  padding: 9px 10px;
  border-radius: 8px;
  background: #f7f3fd;
  color: #6a5886;
  font-size: 9px;
  line-height: 1.5;
}

.co-renew-note-due {
  background: #fff6e8;
  color: #93601d;
}

.co-renew-action {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: 36px;
  padding: 9px 11px;
  border: 0;
  border-radius: 8px;
  background: var(--renew-purple);
  color: #fff;
  font-family: inherit;
  font-size: 10px;
  font-weight: 650;
  text-align: left;
  cursor: pointer;
  transition: background .15s ease;
}

.co-renew-action:hover:not(:disabled) {
  background: #6d4db4;
}

.co-renew-action:disabled {
  background: #b9abd9;
  cursor: not-allowed;
}

/* Empty state and help */
.co-renew-empty {
  padding: 28px 15px;
  border: 1px dashed #d8c9f1;
  border-radius: 12px;
  background: #fff;
  text-align: center;
}

.co-renew-empty strong {
  font-size: 13px;
}

.co-renew-empty p {
  margin: 7px 0 12px;
  color: var(--renew-muted);
  font-size: 10px;
}

.co-renew-empty a,
.co-renew-help a {
  color: #6d4db4;
  font-size: 10px;
  font-weight: 650;
  text-decoration: none;
}

.co-renew-help {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  margin-bottom: 18px;
  border: 1px solid var(--renew-border);
  border-radius: 11px;
  background: #faf7ff;
}

.co-renew-help strong {
  font-size: 11px;
}

.co-renew-help p {
  margin: 4px 0 0;
  color: var(--renew-muted);
  font-size: 9px;
  line-height: 1.5;
}

.co-renew-footer {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 13px 2px;
  border-top: 1px solid #e5dcef;
  color: var(--renew-muted);
  font-size: 9px;
}

.co-renew-footer strong {
  color: #45345f;
}

/* Responsive */
@media (max-width: 760px) {
  .co-renew-layout {
    grid-template-columns: 1fr;
    gap: 14px;
  }

  .co-renew-sidebar {
    min-height: auto;
  }

  .co-renew-sidebar-bottom {
    margin-top: 16px;
  }

  .co-renew-card-list {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .co-renew-page {
    padding: 8px;
  }

  .co-renew-page-header {
    align-items: flex-start;
  }

  .co-renew-page-header h1 {
    font-size: 22px;
  }

  .co-renew-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    row-gap: 14px;
  }

  .co-renew-stats > div:nth-child(2) {
    border-right: 0;
  }

  .co-renew-details {
    gap: 5px;
  }
}




/* =====================================================
   CAMPUSOPS RENEW PAGE — LAYOUT & TYPOGRAPHY CORRECTION
   Append this after the existing CSS.
   ===================================================== */

.co-renew-page {
  padding: 14px 16px;
  min-height: 100vh;
  font-size: 14px;
  color: #30234f;
}

.co-renew-layout {
  grid-template-columns: 220px minmax(0, 1fr);
  gap: 24px;
  max-width: 1440px;
  align-items: stretch;
}

/* Sidebar: match My Rentals proportions */
.co-renew-sidebar {
  padding: 18px 10px 14px;
  min-height: calc(100vh - 28px);
  border-radius: 16px;
}

.co-renew-brand {
  gap: 10px;
  padding: 0 5px 28px;
}

.co-renew-brand-mark {
  width: 36px;
  height: 36px;
  border-radius: 11px;
  font-size: 17px;
}

.co-renew-brand strong {
  font-size: 13px;
}

.co-renew-brand small {
  font-size: 10px;
}

.co-renew-nav-label {
  margin: 0 8px 10px;
  font-size: 9px;
}

.co-renew-nav {
  min-height: 38px;
  gap: 10px;
  padding: 10px;
  margin-bottom: 3px;
  border-radius: 9px;
  font-size: 12px;
}

.co-renew-nav > span {
  width: 15px;
  font-size: 14px;
}

.co-renew-account-label {
  margin-top: 25px;
}

.co-renew-avatar {
  width: 32px;
  height: 32px;
  font-size: 12px;
}

.co-renew-sidebar-bottom strong {
  font-size: 11px;
}

.co-renew-sidebar-bottom small {
  font-size: 10px;
}

/* Main heading */
.co-renew-main {
  min-width: 0;
  padding: 5px 0 0;
}

.co-renew-page-header {
  align-items: flex-start;
  margin-bottom: 22px;
  gap: 18px;
}

.co-renew-eyebrow {
  margin-bottom: 8px;
  font-size: 9px;
  letter-spacing: 1.2px;
}

.co-renew-page-header h1 {
  margin-bottom: 7px;
  font-size: clamp(26px, 2.4vw, 32px);
  line-height: 1.2;
  letter-spacing: -0.7px;
}

.co-renew-page-header p,
.co-renew-intro p,
.co-renew-section-heading p {
  font-size: 12px;
  line-height: 1.6;
}

.co-renew-outline-link {
  padding: 10px 13px;
  border-radius: 9px;
  font-size: 11px;
}

/* Intro panel */
.co-renew-intro {
  gap: 15px;
  padding: 18px;
  margin-bottom: 14px;
  border-radius: 13px;
}

.co-renew-intro-icon {
  width: 42px;
  height: 42px;
  font-size: 23px;
}

.co-renew-intro h2 {
  margin-bottom: 6px;
  font-size: 16px;
}

/* Summary strip */
.co-renew-stats {
  padding: 16px 5px;
  margin-bottom: 25px;
  border-radius: 12px;
}

.co-renew-stats > div {
  padding: 0 18px;
}

.co-renew-stats span {
  margin-bottom: 6px;
  font-size: 11px;
}

.co-renew-stats strong {
  font-size: 23px;
}

/* Feedback: integrated notification, not a browser-looking alert */
.co-renew-notice {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 15px;
  margin: -8px 0 20px;
  border: 1px solid #d8c9f1;
  border-radius: 10px;
  background: #f7f3ff;
  color: #543b82;
  font-size: 12px;
  line-height: 1.5;
}

.co-renew-notice-success {
  border-color: #c8e8d5;
  background: #f0faf4;
  color: #246a47;
}

.co-renew-notice-error {
  border-color: #f0c8d0;
  background: #fff3f5;
  color: #a12e48;
}

.co-renew-notice button {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border: 1px solid currentColor;
  border-radius: 7px;
  background: transparent;
  color: inherit;
  font-size: 17px;
  cursor: pointer;
}

/* Rentals section */
.co-renew-list-section {
  margin-bottom: 22px;
}

.co-renew-section-heading {
  margin-bottom: 13px;
}

.co-renew-section-heading h2 {
  margin-bottom: 5px;
  font-size: 19px;
  line-height: 1.3;
}

.co-renew-search {
  height: 44px;
  gap: 11px;
  padding: 0 14px;
  margin-bottom: 11px;
  border-radius: 10px;
}

.co-renew-search > span {
  font-size: 17px;
}

.co-renew-search input {
  font-size: 12px;
}

.co-renew-search button {
  border: 0;
  background: transparent;
  color: #6947a7;
  font-size: 11px;
  cursor: pointer;
}

.co-renew-filter-row {
  gap: 7px;
  margin-bottom: 14px;
}

.co-renew-filter-row button {
  padding: 9px 12px;
  border-radius: 8px;
  font-size: 11px;
}

.co-renew-filter-row button span {
  margin-left: 3px;
}

/* Rental cards */
.co-renew-card-list {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.co-renew-card {
  min-width: 0;
  padding: 16px;
  border-radius: 13px;
}

.co-renew-card-top {
  margin-bottom: 13px;
}

.co-renew-resource-icon {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  font-size: 17px;
}

.co-renew-status {
  padding: 6px 9px;
  font-size: 10px;
}

.co-renew-resource-type {
  margin-bottom: 5px;
  font-size: 10px;
  letter-spacing: 0.4px;
}

.co-renew-card h3 {
  margin-bottom: 5px;
  font-size: 15px;
  line-height: 1.4;
}

.co-renew-number {
  margin-bottom: 13px;
  font-size: 11px;
}

.co-renew-details {
  gap: 10px;
  padding: 13px 0;
}

.co-renew-details span {
  margin-bottom: 6px;
  font-size: 10px;
}

.co-renew-details strong {
  font-size: 11px;
  line-height: 1.45;
}

.co-renew-note {
  margin: 11px 0;
  padding: 11px 12px;
  border-radius: 9px;
  font-size: 11px;
  line-height: 1.55;
}

.co-renew-action {
  min-height: 40px;
  padding: 11px 13px;
  border-radius: 8px;
  font-size: 12px;
}

/* Empty states and pagination */
.co-renew-empty {
  padding: 32px 18px;
  border-radius: 13px;
}

.co-renew-empty strong {
  font-size: 15px;
}

.co-renew-empty p,
.co-renew-empty a {
  font-size: 12px;
  line-height: 1.6;
}

.co-renew-empty button {
  padding: 9px 13px;
  border: 1px solid #d8c9f1;
  border-radius: 8px;
  background: #fff;
  color: #6947a7;
  font-size: 11px;
  cursor: pointer;
}

.co-renew-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 14px;
  color: #81749b;
  font-size: 11px;
}

.co-renew-page-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.co-renew-page-controls button {
  min-width: 34px;
  min-height: 32px;
  padding: 7px 10px;
  border: 1px solid #e6dcf7;
  border-radius: 8px;
  background: #fff;
  color: #604687;
  font-family: inherit;
  font-size: 11px;
  cursor: pointer;
}

.co-renew-page-controls button.selected {
  border-color: #8062c7;
  background: #8062c7;
  color: #fff;
}

.co-renew-page-controls button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* Support and footer */
.co-renew-help {
  padding: 16px 18px;
  margin-bottom: 20px;
  border-radius: 12px;
}

.co-renew-help strong {
  font-size: 13px;
}

.co-renew-help p,
.co-renew-help a {
  font-size: 11px;
  line-height: 1.6;
}

.co-renew-footer {
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  padding: 15px 2px;
  font-size: 10px;
}

.co-renew-footer-links {
  display: flex;
  gap: 15px;
}

.co-renew-footer a {
  font-size: 10px;
}

/* Responsive layout */
@media (max-width: 900px) {
  .co-renew-layout {
    grid-template-columns: 190px minmax(0, 1fr);
    gap: 16px;
  }

  .co-renew-card-list {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 650px) {
  .co-renew-page {
    padding: 10px;
  }

  .co-renew-layout {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .co-renew-sidebar {
    min-height: auto;
  }

  .co-renew-sidebar-bottom {
    margin-top: 16px;
  }

  .co-renew-page-header {
    flex-direction: column;
  }

  .co-renew-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    row-gap: 15px;
  }

  .co-renew-stats > div:nth-child(2) {
    border-right: 0;
  }

  .co-renew-details {
    gap: 8px;
  }

  .co-renew-pagination {
    align-items: flex-start;
    flex-direction: column;
  }
}

sp_widget.script:
(function() {
  var userId = gs.getUserID();
  var nowMs = new GlideDateTime().getNumericValue();
  var DAY_MS = 86400000;

  data.rentals = [];
  data.activeCount = 0;
  data.dueSoonCount = 0;
  data.overdueCount = 0;
  data.requestedCount = 0;

  // Response fields expected by the Client Controller.
  data.success = false;
  data.message = "";

  function formatDate(value) {
    if (!value) return "";

    try {
      return new GlideDateTime(value)
        .getLocalDate()
        .getByFormat("dd MMM yyyy");
    } catch (e) {
      return "";
    }
  }

  function getRental(rentalId) {
    if (!rentalId) return null;

    var gr = new GlideRecord("u_student_rental");

    if (!gr.get(rentalId)) return null;

    // Only allow the signed-in student to request their own rental.
    if (gr.getValue("u_student") !== userId) return null;

    if ((gr.getValue("u_status") || "").toLowerCase() !== "active") {
      return null;
    }

    return gr;
  }

  /*
   * ACTION: Request renewal
   */
  if (input && input.action === "requestRenewal") {
    var record = getRental(
      (input.rentalId || "").toString()
    );

    if (!record) {
      data.success = false;
      data.message =
        "This active rental could not be found for your account.";
      return;
    }

    if (record.getValue("u_renewal_requested") === "true") {
      data.success = false;
      data.message =
        "A renewal request has already been submitted.";
      return;
    }

    // Do not allow overdue rentals to be submitted through this action.
    var dueValue = record.getValue("u_due_date");

    if (dueValue &&
        new GlideDateTime(dueValue).getNumericValue() < nowMs) {
      data.success = false;
      data.message =
        "This rental is overdue. Please contact the campus desk.";
      return;
    }

    record.setValue("u_renewal_requested", true);

    var updatedId = record.update();

    if (!updatedId) {
      data.success = false;
      data.message =
        "The request could not be saved. Please try again.";
      return;
    }

    data.success = true;
    data.message =
      "Your renewal request has been submitted for processing.";
    return;
  }

  /*
   * LOAD ACTIVE RENTALS FOR THE SIGNED-IN STUDENT
   */
  var rental = new GlideRecord("u_student_rental");
  rental.addQuery("u_student", userId);
  rental.addQuery("u_status", "active");
  rental.orderBy("u_due_date");
  rental.query();

  while (rental.next()) {
    data.activeCount++;

    var dueValue = rental.getValue("u_due_date");
    var dueMs = dueValue
      ? new GlideDateTime(dueValue).getNumericValue()
      : null;

    var daysLeft = dueMs === null
      ? null
      : Math.ceil((dueMs - nowMs) / DAY_MS);

    var isOverdue = dueMs !== null && dueMs < nowMs;

    var isDueSoon = !isOverdue &&
      daysLeft !== null &&
      daysLeft >= 0 &&
      daysLeft <= 2;

    if (isOverdue) {
      data.overdueCount++;
    } else if (isDueSoon) {
      data.dueSoonCount++;
    }

    var assetName =
      rental.getDisplayValue("u_asset") || "Campus resource";

    var assetType = "";

    var asset = rental.u_asset.getRefRecord();

    if (asset && asset.isValidRecord()) {
      assetType = asset.getDisplayValue("u_asset_type") || "";
    }

    var requested =
      rental.getValue("u_renewal_requested") === "true";

    if (requested) {
      data.requestedCount++;
    }

    data.rentals.push({
      id: rental.getUniqueValue(),
      number: rental.getDisplayValue("u_number"),
      assetName: assetName,
      type: assetType,
      dueDate: formatDate(dueValue),
      dueMs: dueMs,
      isOverdue: isOverdue,
      isDueSoon: isDueSoon,
      renewalCount: parseInt(
        rental.getValue("u_renewal_count") || "0",
        10
      ) || 0,
      requested: requested,
      renewalRequested: requested,
      riskLabel:
        rental.getDisplayValue("u_return_risk") || "Not assessed"
    });
  }
})();
